window.docContents[204].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Terms":{"contents":"Besides the usual variables, abstractions, applications,\nterms related to natural numbers, and unit, we need four\nmore sorts of terms to handle mutable references:\n\nt ::= \"ref\" t    (\"reference\")\n    | \"!\"t       (\"dereference\")\n    | t \":=\" t   (\"assignment\")\n    | l          (\"location\");\n\n\ninductive Tm  : Type :=\n  -- STLC with numbers:\n  | var    : String → Tm\n  | app    : Tm → Tm → Tm\n  | abs    : String → Ty → Tm → Tm\n  | const  : Nat → Tm\n  | succ    : Tm → Tm\n  | pred    : Tm → Tm\n  | mult    : Tm → Tm → Tm\n  | ite0  : Tm → Tm → Tm → Tm\n  -- New terms:\n  | unit   : Tm\n  | ref    : Tm → Tm\n  | deref  : Tm → Tm\n  | assign : Tm → Tm → Tm\n  | loc    : Nat → Tm\n\n\nscoped syntax:max num : stlcTm\nscoped syntax:60 stlcTm:60 \" * \" stlcTm:61 : stlcTm\nscoped syntax:50 \"if0 \" stlcTm:51 \" then \" stlcTm:50 \" else \" stlcTm:50 : stlcTm\n\nscoped syntax:60 stlcTm:60 \" := \" stlcTm:61 : stlcTm\nscoped syntax:60 \"Ref \" stlcTy:61 : stlcTy\nscoped syntax:60 \"ref \" stlcTm:61 : stlcTm\nscoped syntax:60 \"loc \" stlcTm:61 : stlcTm\nscoped syntax:60 \"!\" stlcTm:61 : stlcTm\nscoped syntax:55 stlcTm:56 \" ; \" stlcTm:55 : stlcTm\n\nscoped syntax stlcCtx \" / \" term:max \" ⊢ \" stlcTm \" ⦂ \" stlcTy : stlcQuoted\n\nabbrev Tm.tseq t₁ t₂ :=\n  Tm.app (.abs \"X\" .unit t₂) t₁\n\nnamespace Elab\n\nopen StlcCommon\nopen Lean Meta Elab Term\n\ndef language : Language where\n  tyType := ``Ty\n  tmType := ``Tm\n  arrowCtor := ``Ty.arrow\n  varCtor := ``Tm.var\n  appCtor := ``Tm.app\n  absCtor := ``Tm.abs\n  -- defined later\n  subst := `STLCRef.subst\n  hasType := `STLCRef.HasType\n\ndef extendedTyHandler : TyElabHandler :=\n  fun recur k T => do\n    match T with\n    | `(stlcTy| Nat) =>\n        return mkConst ``Ty.nat\n    | `(stlcTy| Unit) =>\n        return mkConst ``Ty.unit\n    | `(stlcTy| Ref $τ:stlcTy) => do\n        let τ ← recur τ\n        return mkApp (mkConst ``Ty.ref) τ\n    | _ => k T\n\ndef tyHandlers : TyElabHandler :=\n  extendedTyHandler.orElse (commonTyHandler language)\n\npartial def elabTy : TyElab :=\n  tyHandlers elabTy <| unsupportedTy language\n\ndef extendedTmHandler : TmElabHandler :=\n  fun recur k Γ free t => do\n    match t with\n    | `(stlcTm| $n:num) => do\n        return (mkApp (mkConst ``Tm.const) (mkNatLit n.getNat), free )\n\n    | `(stlcTm| Nat) => do\n        throwError \"`Nat` is not a valid term.\"\n\n    | `(stlcTm| succ $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.succ) t, free)\n\n    | `(stlcTm| pred $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.pred) t, free)\n\n    | `(stlcTm| $t₁:stlcTm * $t₂:stlcTm) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.mult) t₁ t₂, free)\n\n    | `(stlcTm| if0 $c:stlcTm then $t:stlcTm else $e:stlcTm) => do\n        let (c, free) ← recur Γ free c\n        let (t, free) ← recur Γ free t\n        let (e, free) ← recur Γ free e\n        return (mkApp3 (mkConst ``Tm.ite0) c t e, free)\n\n    | `(stlcTm| Unit) => do\n        throwError \"`Unit` is not a valid term.\"\n\n    | `(stlcTm| unit) => do\n        return (mkConst ``Tm.unit, free)\n\n    | `(stlcTm| ref $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.ref) t, free)\n\n    | `(stlcTm| !$t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.deref) t, free)\n\n    | `(stlcTm| loc $n:num) => do\n        return (mkApp (mkConst ``Tm.loc) (mkNatLit n.getNat), free )\n\n    | `(stlcTm| $t₁:stlcTm := $t₂:stlcTm) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.assign) t₁ t₂, free)\n\n    | `(stlcTm| $t₁:stlcTm ; $t₂:stlcTm) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.tseq) t₁ t₂, free)\n\n    | _ => k Γ free t\n\ndef tmHandlers : TmElabHandler :=\n  extendedTmHandler.orElse (commonTmHandler language elabTy)\n\npartial def elabTm : TmElab :=\n  tmHandlers elabTm unsupportedTm\n\ndef elabCtx : CtxElab := elabCtxCommon language elabTy\n\n-- `HasType` takes the store typing as an extra first argument,\n-- so we build typing judgments here instead of in `elabQuoted`.\ndef mkHasType (δ Γ t T : Expr) : TermElabM Expr := do\n  let some hasType ← resolveId? (mkIdent language.hasType)\n    | throwError \"unknown declaration `{language.hasType}`\"\n  return mkApp4 hasType δ Γ t T\n\n@[scoped term_elab StlcCommon.bracket]\ndef elabBracket : TermElab :=\n  fun stx expectedType? => do\n    match stx with\n    | `(<{ $Γ:stlcCtx / $δ:term ⊢ $t:stlcTm ⦂ $T:stlcTy }>) => do\n        let (Γ, scope) ← elabCtx Γ\n        let (t, _) ← elabTm scope [] t\n        let T ← elabTy T\n        let δ ← elabTermEnsuringType δ (mkApp (mkConst ``List [levelZero]) (mkConst ``Ty))\n        mkHasType δ Γ t T\n    | `(<{ $_:stlcCtx ⊢ $_:stlcTm ⦂ $_:stlcTy }>) =>\n        throwError \"typing judgments need a store typing: write `Γ / δ ⊢ t ⦂ τ`\"\n    | `(<{ $q:stlcQuoted }>) =>\n        elabQuoted language elabTy elabTm elabCtx q expectedType?\n    | _ => throwUnsupportedSyntax\n\nend Elab\n\nopen scoped Elab\n\nnamespace Delab\n\nopen StlcCommon Elab Delab\nopen Lean PrettyPrinter Delaborator\n\n@[app_unexpander Ty.nat]\nprivate def Ty.unexpandNat : Unexpander\n  | stx => do\n    let Nat := mkObjectIdentFrom stx \"Nat\"\n    let T ← `(stlcTy| $Nat:ident)\n    `(<{ $T:stlcTy }>)\n\n@[app_unexpander Ty.unit]\nprivate def Ty.unexpandUnit : Unexpander\n  | stx => do\n    let Unit := mkObjectIdentFrom stx \"Unit\"\n    let T ← `(stlcTy| $Unit:ident)\n    `(<{ $T:stlcTy }>)\n\n@[app_unexpander Ty.arrow]\nprivate def Ty.unexpandArrow : Unexpander := Delab.unexpandArrow\n\n@[app_unexpander Ty.ref]\nprivate def Ty.unexpandRef : Unexpander\n  | `($_ $T) => do\n      let T' := getTy T\n      `(<{ Ref $T':stlcTy }>)\n  | _ => throw ()\n\nprivate def reservedNames : String → Bool\n  | \"Nat\" | \"Unit\" | \"succ\" | \"pred\"\n  | \"if0\" | \"ref\" | \"loc\" | \"Ref\"\n  | \"unit\" => true\n  | _ => false\n\n@[app_unexpander Tm.var]\nprivate def Tm.unexpandVar : Unexpander := Delab.unexpandVar reservedNames ``Tm.var\n\n@[app_delab Tm.var]\nprivate def Tm.delabVar : Delab := Delab.delabVar ``Tm.var\n\n@[app_unexpander Tm.app]\nprivate def Tm.unexpandApp : Unexpander := Delab.unexpandApp\n\n@[app_unexpander Tm.abs]\nprivate def Tm.unexpandAbs : Unexpander := Delab.unexpandAbs\n\n@[app_unexpander Tm.const]\nprivate def Tm.unexpandConst : Unexpander\n  | `($_ $n:num) => `(<{ $n:num }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.succ]\nprivate def Tm.unexpandSucc : Unexpander\n  | stx@`($_ $t) => do\n      let succ := mkObjectIdentFrom stx \"succ\"\n      let t' := getTm t\n      `(<{ $succ:ident $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.pred]\nprivate def Tm.unexpandPred : Unexpander\n  | stx@`($_ $t) => do\n      let pred := mkObjectIdentFrom stx \"pred\"\n      let t' := getTm t\n      `(<{ $pred:ident $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.mult]\nprivate def Tm.unexpandMult : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ $t₁':stlcTm * $t₂':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.tseq]\nprivate def Tm.unexpandTseq : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ $t₁':stlcTm ; $t₂':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.ite0]\nprivate def Tm.unexpandIte0 : Unexpander\n  | `($_ $c $t $e) => do\n      let c' := getTm c\n      let t' := getTm t\n      let e' := getTm e\n      `(<{ if0 $c':stlcTm then $t':stlcTm else $e':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.unit]\nprivate def Tm.unexpandUnit : Unexpander\n  | stx => do\n      let unit := mkObjectIdentFrom stx \"unit\"\n      let t ← `(stlcTm| $unit:ident)\n      `(<{ $t:stlcTm }>)\n\n@[app_unexpander Tm.assign]\nprivate def Tm.unexpandAssign : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ $t₁':stlcTm := $t₂':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.ref]\nprivate def Tm.unexpandRef : Unexpander\n  | `($_ $t₁) => do\n      let t₁' := getTm t₁\n      `(<{ ref $t₁':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.deref]\nprivate def Tm.unexpandDeref : Unexpander\n  | `($_ $t₁) => do\n      let t₁' := getTm t₁\n      `(<{ !$t₁':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.loc]\nprivate def Tm.unexpandLoc : Unexpander\n  | `($_ $n:num) => `(<{ loc $n:num }>)\n  | _ => throw ()\n\nend Delab\n\n\n/-- info: <{ unit }> : Tm -/\n#guard_msgs in\n#check <{ unit }>\n\n/-- info: <{ Nat }> : Ty -/\n#guard_msgs in\n#check (Ty.nat : Ty)\n\n/-- info: <{ Ref Nat }> : Ty -/\n#guard_msgs in\n#check (Ty.ref Ty.nat : Ty)\n\n/-- info: <{ Unit }> : Ty -/\n#guard_msgs in\n#check (Ty.unit : Ty)\n\n/-- info: <{ unit }> : Tm -/\n#guard_msgs in\n#check (Tm.unit : Tm)\n\n/-- info: <{ 0 }> : Tm -/\n#guard_msgs in\n#check (Tm.const 0 : Tm)\n\nexample (x : Tm) : (<{ x }> : Tm) = x := by rfl\n\n/-- info: <{ λ X : Nat . X }> : Tm -/\n#guard_msgs in\n#check <{ λ X : Nat. X }>\n\n/-- info: <{ if0 X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 X then X else X }>\n\n/-- info: <{ if0 Y X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 Y X then X else X }>\n\n/-- info: <{ if0 Y X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 (Y X) then X else X }>\n\n/-- info: <{ X * Y * Z }> : Tm -/\n#guard_msgs in\n#check <{ X * Y * Z }>\n\n/-- info: <{ succ (pred X) }> : Tm -/\n#guard_msgs in\n#check <{ succ (pred X) }>\n\n/-- info: <{ succ X Y }> : Tm -/\n#guard_msgs in\n#check <{ succ X Y }>\n\n/-- info: <{ ref (λ X : Unit . X) }> : Tm -/\n#guard_msgs in\n#check <{ ref (λ X : Unit . X) }>\n\n/-- info: <{ !X }> : Tm -/\n#guard_msgs in\n#check <{ !X }>\n\n/-- info: <{ loc 3 }> : Tm -/\n#guard_msgs in\n#check <{ loc 3 }>\n\n\nIntuitively:* ref t (formally, ref t) allocates a new reference cell\n  with the value τ and reduces to the location of the newly\n  allocated cell;* !t (formally, deref t) reduces to the contents of the\n  cell referenced by τ;* t₁ := t₂ (formally, assign t₁ t₂) assigns t₂ to the\n  cell referenced by t₁; and* l (formally, loc l) is a reference to the cell at\n  location l.  We'll discuss locations later.\n\nIn informal examples, we'll also freely use the extensions\nof the STLC developed in the MoreStlc chapter; however, to keep\nthe proofs small, we won't bother formalizing them again here.  (It\nwould be easy to do so, since there are no very interesting\ninteractions between those features and references.)\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Definitions","header":"9.1.3. Terms","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Terms"},"/Sub/#Type-Systems--Sub___-Subtyping--Concepts--Subtyping-and-Object-Oriented-Languages":{"contents":"Subtyping plays a fundamental role in many programming\nlanguages -- in particular, it is central to the design of\nobject-oriented languages and their libraries.An object in Java, C#, etc. can be thought of as a record,\nsome of whose fields are functions (\"methods\") and some of whose\nfields are data values (\"fields\" or \"instance variables\").\nInvoking a method m of an object o on some arguments a₁..an\nroughly consists of projecting out the m field of o and\napplying it to a₁..an.The type of an object is called a class -- or, in some\nlanguages, an interface.  It describes which methods and which\ndata fields the object offers.  Classes and interfaces are related\nby the subclass and subinterface relations.  An object\nbelonging to a subclass (or subinterface) is required to provide\nall the methods and fields of one belonging to a superclass (or\nsuperinterface), plus possibly some more.The fact that an object from a subclass can be used in place of\none from a superclass provides a degree of flexibility that is\nextremely handy for organizing complex libraries.  For example, a\nGUI toolkit like Java's Swing framework might define an abstract\ninterface Component that collects together the common fields and\nmethods of all objects having a graphical representation that can\nbe displayed on the screen and interact with the user, such as the\nbuttons, checkboxes, and scrollbars of a typical GUI.  A method\nthat relies only on this common interface can now be applied to\nany of these objects.Of course, real object-oriented languages include many other\nfeatures besides these.  For example, fields can be updated.\nFields and methods can be declared \"private\".  Classes can give\ninitializers that are used when constructing objects.  Code in\nsubclasses can cooperate with code in superclasses via\ninheritance.  Classes can have static methods and fields.  Etc.,\netc.To keep things simple here, we won't deal with any of these\nissues -- in fact, we won't even talk any more about objects or\nclasses.  (There is a lot of discussion in , if\nyou are interested.)  Instead, we'll study the core concepts\nbehind the subclass / subinterface relation in the simplified\nsetting of the STLC.\n\n\n\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Concepts","header":"8.1.2. Subtyping and Object-Oriented Languages","id":"/Sub/#Type-Systems--Sub___-Subtyping--Concepts--Subtyping-and-Object-Oriented-Languages"}});